        test('associateRecordToEmail uses createRecord output correctly', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject({}),
                'associate-record-to-email.now.ts',
                'core-actions/fluent'
            )

            const actions = merged['sys_hub_action_instance_v2']

            // Find associateRecordToEmail action
            const associateAction = actions.find((action: any) => {
                if (!action || !action.values) {
                    return false
                }
                const inputs = unzipInputArray(action.values)
                return inputs.some((input: any) => input.name === 'email_record')
            })

            const associateInputs = unzipInputArray(associateAction.values)

            const targetRecordInput = findInput(associateInputs, 'target_record')

            // Verify it references the createRecord action's output
            expect(targetRecordInput.value).toContain('record')
            // The value should be a data pill reference to the previous action's output
            expect(targetRecordInput.value).toMatch(/\{\{.*\.record\}\}/)
        })

