            expect(content).toContain("table: 'incident'")
            expect(content).toContain('params.trigger.current.sys_id')
            expect(content).toContain("additional_comments: 'Test worknote added by flow'")
            expect(content).toContain("journal_field: 'work_notes'")

            // Verify log action
            expect(content).toContain('action.core.log')
            expect(content).toContain("log_level: 'info'")
            expect(content).toContain('addWorknoteLinkToContext outputs')

